'use strict';
const initial=`precision mediump float;
uniform float u_time;uniform vec2 u_resolution;uniform vec2 u_mouse;uniform float u_audio;
void main(){vec2 p=(gl_FragCoord.xy*2.-u_resolution)/u_resolution.y;vec2 m=(u_mouse*2.-1.)*vec2(u_resolution.x/u_resolution.y,1.);float t=u_time*.2;float w=sin(p.x*3.+sin(p.y*3.+t))*cos(p.y*2.-t);float r=length(p-m*.25);float f=sin(w*3.+r*4.-t*2.);float line=pow(.5+.5*sin(f*5.+p.y*3.),12.);vec3 base=mix(vec3(.025,.065,.1),vec3(.22,.55,.58),.5+.5*f);vec3 col=base+line*vec3(.66,.83,.78)*.7;col*=.55+.45*max(0.,1.-length(p)*.3);gl_FragColor=vec4(col,1.);}`;
let current={title:'流动的月银',fragment:initial,palette:['#408d94','#d0e8dc'],description:'移动光标，拨动这片物质'},gl,program,frame,t0=performance.now(),last=0,mouse=[.5,.5];const canvas=document.querySelector('#scene'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function shader(type,src){let s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)){let error=gl.getShaderInfoLog(s);gl.deleteShader(s);throw Error('材质编译失败 · '+error.slice(0,95))}return s}
function compile(fragment){if(typeof fragment!=='string'||fragment.length>16000)throw Error('材质源文件无效');const vertex=shader(gl.VERTEX_SHADER,'attribute vec2 a;void main(){gl_Position=vec4(a,0.,1.);}');let frag,p;try{frag=shader(gl.FRAGMENT_SHADER,fragment);p=gl.createProgram();gl.attachShader(p,vertex);gl.attachShader(p,frag);gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error('材质连接失败');}catch(e){if(p)gl.deleteProgram(p);throw e}finally{gl.deleteShader(vertex);if(frag)gl.deleteShader(frag)}if(program)gl.deleteProgram(program);program=p;gl.useProgram(program);let a=gl.getAttribLocation(program,'a');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);draw(performance.now(),true)}
function draw(now,force=false){if(stopped||!program)return;if(force||now-last>=(reduced?500:1000/30)){last=now;gl.useProgram(program);gl.uniform1f(gl.getUniformLocation(program,'u_time'),reduced?0:(now-t0)/1000);gl.uniform2f(gl.getUniformLocation(program,'u_resolution'),320,240);gl.uniform2f(gl.getUniformLocation(program,'u_mouse'),...mouse);gl.uniform1f(gl.getUniformLocation(program,'u_audio'),0);gl.drawArrays(gl.TRIANGLE_STRIP,0,4)}if(!force)frame=requestAnimationFrame(draw)}
function apply(r){compile(r.fragment);current={title:String(r.title||'无名物质').slice(0,40),fragment:r.fragment,palette:r.palette,description:String(r.description||'你的语言，成为新的物质').slice(0,180)};document.querySelector('#title').textContent=current.title;document.querySelector('#caption').textContent=current.description;status('作品已生成 · 可继续修改或保存')}
canvas.addEventListener('pointermove',e=>{let r=canvas.getBoundingClientRect();mouse=[(e.clientX-r.left)/r.width,1-(e.clientY-r.top)/r.height]});
document.querySelector('#generate').onclick=()=>generate('visual',current,apply);document.querySelector('#save').onclick=()=>saveState(current);
(async()=>{try{gl=canvas.getContext('webgl',{alpha:false,antialias:false,preserveDrawingBuffer:false,powerPreference:'low-power'});if(!gl)throw Error('设备未提供 WebGL，请检查图形驱动');let buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);compile(initial);frame=requestAnimationFrame(draw);try{let s=await AtomApp.load(current);apply(s);loaded=true;status('本地材质 · 输入一句话，让 AI 改造')}catch(e){status('读取失败 · 请重新打开，原作品不会被覆盖')}document.querySelector('#generate').disabled=!loaded}catch(e){status(e.message)}AtomApp.ready()})();
AtomApp.onSuspend(()=>{cancelAnimationFrame(frame);if(gl){if(program)gl.deleteProgram(program);gl.getExtension('WEBGL_lose_context')?.loseContext()}});
